const r = $input.first().json.report || {};
const t = r.totals || {};
const byType = Array.isArray(r.by_type) ? r.by_type : [];
const byProject = Array.isArray(r.by_project) ? r.by_project : [];
const recent = Array.isArray(r.recent_critical) ? r.recent_critical : [];

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function money(n) { return n != null && n > 0 ? Number(n).toLocaleString('es-ES') + ' EUR' : '-'; }
function dateShort(s) { if (!s) return '-'; return new Date(s).toISOString().substring(0,10); }
const sevColor = { low:'#888', medium:'#3b82f6', high:'#e67e22', critical:'#c00' };

const rowsType = byType.map(x => `<tr>
  <td>${esc(x.type)}</td>
  <td style="text-align:right">${x.total}</td>
  <td style="text-align:right;font-weight:600">${x.unresolved_count}</td>
  <td style="text-align:right;color:${x.critical_count > 0 ? '#c00' : '#666'};font-weight:600">${x.critical_count}</td>
  <td style="text-align:right">${x.safety_count}</td>
  <td style="text-align:right">${money(x.avg_cost)}</td>
</tr>`).join('');

const rowsProj = byProject.map(p => {
  const cls = p.critical_unresolved > 0 ? ' style="background:#fee"' : '';
  return `<tr${cls}>
    <td><a href="/webhook/admin-project?project_id=${esc(p.project_id)}" style="color:#1f2937">${esc(p.project_name)}</a></td>
    <td>${esc(p.current_phase)}</td>
    <td style="text-align:right">${p.total}</td>
    <td style="text-align:right;font-weight:600">${p.unresolved_count}</td>
    <td style="text-align:right;color:${p.critical_unresolved > 0 ? '#c00' : '#666'};font-weight:600">${p.critical_unresolved}</td>
  </tr>`;
}).join('');

const rowsRecent = recent.map(f => `<tr style="background:${f.affects_safety ? '#fee' : (f.severity === 'critical' ? '#fff8e0' : '#fff')}">
  <td><span style="background:${sevColor[f.severity] || '#888'};color:white;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:bold">${esc(f.severity)}</span>${f.affects_safety ? ' <strong style="color:#c00">SAFETY</strong>' : ''}</td>
  <td>${esc(f.type)}</td>
  <td>${esc(f.project_name)}</td>
  <td>${esc(f.status)}</td>
  <td style="font-size:12px;color:#555">${esc(f.desc_preview)}...</td>
  <td>${dateShort(f.created_at)}</td>
</tr>`).join('');

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Pathology Overview - ArquitAI</title>
<style>
  body{font-family:system-ui,sans-serif;max-width:1200px;margin:32px auto;padding:0 20px;color:#222;background:#f7f7f8}
  h1{margin:0 0 8px}
  .sub{color:#888;font-size:13px;margin-bottom:24px}
  h2{margin:32px 0 12px;font-size:18px;border-bottom:1px solid #ddd;padding-bottom:6px}
  .cards{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:24px}
  .card{background:#fff;border:1px solid #ddd;border-radius:8px;padding:14px;text-align:center}
  .card h3{margin:0 0 4px;font-size:11px;color:#666;text-transform:uppercase;letter-spacing:.5px}
  .card .v{font-size:24px;font-weight:600}
  table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #ddd;border-radius:8px;overflow:hidden;font-size:13px}
  th,td{padding:8px 10px;border-bottom:1px solid #eee;text-align:left}
  th{background:#f0f0f3;font-weight:600;font-size:11px;text-transform:uppercase;color:#555}
  tr:last-child td{border-bottom:none}
  .meta{font-size:12px;color:#888;margin-top:24px}
  @media (max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}}
</style></head><body>
<h1>Pathology Overview - ArquitAI</h1>
<p class="sub">Vista agregada de patologias detectadas. Para drill-down: /webhook/admin-project?project_id=&lt;uuid&gt;.</p>
<div class="cards">
  <div class="card"><h3>Total findings</h3><div class="v">${t.total_findings || 0}</div></div>
  <div class="card"><h3>Unresolved</h3><div class="v" style="color:${t.unresolved > 0 ? '#e67e22' : '#27ae60'}">${t.unresolved || 0}</div></div>
  <div class="card"><h3>Critical unresolved</h3><div class="v" style="color:${t.critical_unresolved > 0 ? '#c00' : '#27ae60'}">${t.critical_unresolved || 0}</div></div>
  <div class="card"><h3>Safety unresolved</h3><div class="v" style="color:${t.safety_unresolved > 0 ? '#c00' : '#27ae60'}">${t.safety_unresolved || 0}</div></div>
  <div class="card"><h3>In repair</h3><div class="v">${t.in_repair || 0}</div></div>
</div>
<h2>Por tipo de patologia</h2>
<table>
  <thead><tr><th>tipo</th><th style="text-align:right">total</th><th style="text-align:right">unresolved</th><th style="text-align:right">critical</th><th style="text-align:right">safety</th><th style="text-align:right">avg coste max</th></tr></thead>
  <tbody>${rowsType || '<tr><td colspan="6" style="text-align:center;color:#888;padding:18px">Sin findings registrados</td></tr>'}</tbody>
</table>
<h2>Por proyecto (con findings unresolved)</h2>
<table>
  <thead><tr><th>proyecto</th><th>fase</th><th style="text-align:right">total</th><th style="text-align:right">unresolved</th><th style="text-align:right">critical</th></tr></thead>
  <tbody>${rowsProj || '<tr><td colspan="5" style="text-align:center;color:#888;padding:18px">Sin proyectos con findings unresolved</td></tr>'}</tbody>
</table>
<h2>Recientes critical/safety unresolved</h2>
<table>
  <thead><tr><th>severidad</th><th>tipo</th><th>proyecto</th><th>status</th><th>descripcion</th><th>creado</th></tr></thead>
  <tbody>${rowsRecent || '<tr><td colspan="6" style="text-align:center;color:#888;padding:18px">Sin findings critical/safety unresolved (estado saludable)</td></tr>'}</tbody>
</table>
<div class="meta">Generado ${new Date().toISOString()}</div>
</body></html>`;

return [{ json: { html } }];
